import { strict as assert } from 'node:assert';
import { readFileSync, writeFileSync, statfsSync } from 'node:fs';
import { discoverInventory, validateInventory, sourceHash } from '../scripts/quality-inventory';
const root='.planning/memory-resilience/',stem='.git/q100-batch-';
const text=(p:string)=>readFileSync(p,'utf8'),read=(p:string)=>JSON.parse(text(p)),save=(p:string,v:unknown)=>writeFileSync(p,JSON.stringify(v,null,2)+'\n');
const current=read(stem+'compat.json'),native=read(stem+'native.json'),measure=read(stem+'measure.json'),faults=read(stem+'faults.json');
for(const report of[current,native,measure,faults])for(const row of report.sourceInputs)assert.equal(sourceHash(text(row.path)),row.sourceHash,row.path);
assert.equal(native.runs.length,1);for(const r of[current,...native.runs]){assert.equal(r.exit,0);for(const expected of['275 pass','1183 expect()','0 fail'])assert(r.output.includes(expected),expected);}
assert.equal(faults.runs.length,10);assert.equal(faults.runs[0].exit,0);for(const r of faults.runs.slice(1)){assert.equal(r.exit,1);assert(r.output.includes('(fail)'));}assert.equal(measure.runs[0].exit,0);
assert.equal(text(stem+'test-types.txt').trim(),'');assert(!text(stem+'types.txt').includes('error TS'));assert(text(stem+'isolation.txt').includes('PASS (no violations)'));
assert(text(stem+'red.txt').includes('6 fail'));assert(text(stem+'retry-red.txt').includes('"added":2,"updated":2,"superseded":2,"skipped":1'));assert(text(stem+'retry-red.txt').includes('"sourceChanged":true'));
const evidence=root+'evidence/Q100.4.2.2.1.json',ledger=read(root+'work-items.json'),get=(id:string)=>{const item=ledger.items.find((i:any)=>i.id===id);assert(item,id);return item;};
const item=get('Q100.4.2.2.1'),next=get('Q100.4.2.2.2');assert.equal(item.status,'active');assert.equal(next.status,'pending');
for(const id of[item.id,next.id,'Q100.4.2.2','Q100.4.2','Q100.4.2.11','Q100.4.3','Q005'])get(id).evidence.push(evidence);
item.status='verified';item.progress={status:'Scoped uninterrupted-batch behavior verified; retry and final quality remain required',completed:'Eight real-store cases cover exact/lexical/vector duplicates, evolving replacement chains, retired exact/semantic repeats, exclusion of retired replacement targets, paired vectors and stable UUID tie order. Source replay and stored audit counts verified.275tests/1183assertions across13files per Windows runtime;9targeted faults detected.',next:'Q100.4.2.2.2: fix retained kill-before-audit replacement-chain retry counterexample.',evidence};
item.observed_gap='Uninterrupted comparison contract proved for covered scenarios. Interrupted retry has a retained native failure and remains required in the next child. Full Tier S/file/package/platform/review acceptance remains under Q100.4.3/B10/R02.';
next.status='active';next.observed_gap='Real child accepts alpha->beta->gamma replacement chain, then is killed before audit. Source is retained and SQLite rolls back. Fresh retry appends two more replacements, reports added=2/updated=2/superseded=2/skipped=1, changes source, and leaves beta active instead of gamma. In-memory working-set repair does not establish durable batch identity.';
next.progress={status:'Native RED retained; durable retry design/implementation required',next:'Inspect current event metadata and replay/governance contracts; derive a durable batch identity and completion/recovery contract before implementation. Qualify restart at each replacement/add/supersedence/audit boundary with changed input, force and provider output; do not infer success from merely skipping an existing content match. Coordinate Q100.4.2.11 and preserve privacy/source compatibility.',evidence};ledger.current_item=next.id;
get('Q100.4.2.2').observed_gap='Q100.4.2.2.1 verifies uninterrupted decisions. Q100.4.2.2.2 remains active on the retained native interrupted-chain RED. Parent is pending and cannot pass until retry and both child contracts are proved.';
get('Q100.4.2.2').progress={status:'Uninterrupted comparison child verified; interrupted retry active',next:next.progress.next,evidence};
get('Q100.4.2').observed_gap='Session input/audit admission and uninterrupted batch comparison have scoped behavioral evidence. Interrupted replacement-chain retry changes the source and final active result after kill-before-audit. Remote/Git/maintenance, direct DB topology, durability/reconciliation/scaling and final quality remain required. Parent remains pending.';
get('Q100.4.2').progress={...get('Q100.4.2').progress,status:'Uninterrupted batch decisions verified; interrupted batch child active',next:next.progress.next,batchDecisionEvidence:evidence};
get('Q100.4.2.11').observed_gap+=' Native replacement-chain counterexample now retained: kill after source/replay but before audit, then retry produces two duplicate replacement effects and the wrong final active candidate. Durable operation identity/outcome recovery must cover this; single-fact retry proof is insufficient.';
get('Q005').observed_gap='Uninterrupted batch comparison now sees accepted additions/replacements, keeps vectors paired, ignores retired replacement targets and uses stable initial ties.275tests/1183assertions per Windows runtime,9targeted faults detected. Native interrupted replacement-chain RED remains; final per-file/package Tier S quality and privacy/validation obligations remain.';
get('Q100.4.3').observed_gap+=' Batch checkpoint:275tests/1183assertions per Windows runtime and9detected targeted faults. Narrow pipeline/test diagnostics still below required metrics; no final platform/package/changed-line/review acceptance. Initial wrong-vector mutant survived; extended replacement chain now detects it. Native batch retry RED remains unresolved.';
const catalog=discoverInventory(process.cwd()),manifest=read(root+'quality-classifications.json');assert.equal(catalog.files.length,500);
for(const m of measure.measurement.files){const file=catalog.files.find(f=>f.path===m.path);assert(file);let row=manifest.files.find((r:any)=>r.path===m.path);if(!row){row={path:m.path,package:'package.json',tier:'S',rationale:'Real-store extraction decision and supersedence integrity tests.',applicability:{mode:'measure',reason:'Executable integrity tests; no coverage exclusion approved.'},decisionStatus:'proposed - independent review pending'};manifest.files.push(row);}row.sourceHash=file.sourceHash;row.inspection={sourceRevision:'21dd22c + current source hash',anchor:item.id,scope:'Uninterrupted batch behavior and diagnostic; interrupted retry and final quality remain open'};row.metricApplicability={status:'Scoped diagnostic; full quality pending',sourceHash:file.sourceHash,evidence,metrics:Object.fromEntries(['statements','branches','functions','lines'].map(name=>[name,{observedCounterTotal:m.metrics[name].total,observedPercent:m.metrics[name].pct,proposal:'measure - completeness unverified'}]))};}
assert.deepEqual(validateInventory(catalog,manifest),[]);const items=new Map<string,any>(ledger.items.map((i:any)=>[i.id,i])),done=new Set<string>();
function visit(id:string,stack=new Set<string>()){assert(items.has(id)&&!stack.has(id));if(done.has(id))return;for(const dep of items.get(id).depends_on)visit(dep,new Set([...stack,id]));done.add(id);}for(const id of items.keys())visit(id);
assert.equal(items.size,270);assert.deepEqual(ledger.items.filter((i:any)=>i.status==='active').map((i:any)=>i.id),[next.id]);
const free=statfsSync(process.cwd());const limits=[item.observed_gap,next.observed_gap,'The narrow diagnostic omits native processes and broader passing compatibility tests. Pipeline, old tests and new tests still have metric gaps; no exclusions approved. Same final-source independent review, hosted/Linux, install and two-machine acceptance remain open.','Existing similarity thresholds and provider candidate order are preserved. Retired entries detect repeats at duplicate threshold but cannot be replacement targets. In-memory entries do not persist a batch journal.','No canonical data/model/provider/hook/replication/installation or worktree authority changed. Previously rejected cleanup and shared-temp12KiB authority remain untouched. Three inboxes and R03/P03/A03 decisions remain; embedding experiment follows baseline acceptance.'];
save(evidence,{item_id:item.id,status:'verified - scoped uninterrupted batch behavior',recordedAt:new Date().toISOString(),startingRevision:'21dd22c65704b6d9be5bb05291c5b92cb5a8048c',cwd:process.cwd(),verification:item.verification,outcome:item.progress.completed,current,native,diagnosticCoverage:measure,decisionChecks:faults,red:{exit:1,output:text(stem+'red.txt')},nextCounterexample:{item:next.id,exit:1,source:text(stem+'retry.test.ts'),preparer:text(stem+'prepare.ts'),output:text(stem+'retry-red.txt'),reason:next.observed_gap},corrections:{initialFaults:read(stem+'initial-faults.json'),initialNative:read(stem+'initial-native.json'),initialCollectorError:text(stem+'initial-collector-error.txt'),reason:'Initial vector test did not detect reuse of the first vector after a second replacement. Added a third replacement and its chain assertion, then repeated final collectors. Initial current-runtime collector output path was also used for shell redirection, causing Windows EBUSY while saving output; no current-runtime acceptance claimed from that lost run. Corrected distinct driver/output paths and reran. Pinned initial group passed but is superseded by final test-revision evidence.'},checks:[{command:'bun run typecheck',exit:0,output:text(stem+'types.txt')},{command:'Strict new-test compilation',exit:0,config:read(stem+'tests-tsconfig.json'),output:text(stem+'test-types.txt')},{command:'bun run test:isolation',exit:0,output:text(stem+'isolation.txt')}],limits,disk:{freeBytes:free.bavail*free.bsize},validation:{catalogFiles:500,packages:catalog.packages.length,ledgerItems:270,acyclic:true,currentItem:ledger.current_item,source:text(stem+'checkpoint.ts')}});
save(root+'work-items.json',ledger);save(root+'executable-catalog.json',catalog);save(root+'quality-classifications.json',manifest);console.log(JSON.stringify({verified:item.id,active:next.id,files:500,items:270,freeGiB:(free.bavail*free.bsize/2**30).toFixed(2)}));
